{"version":3,"sources":["dark.scss","_variables.scss","dark.css"],"names":[],"mappings":"AAGA;EACC,yBCeY;ACjBb;AFIC;EACC,wCAAA;AEFF;AFME;EACC,cCiCK;ACrCR;AFOE;EACC,gCAAA;AELH;AFSC;EACC,yBCwBM;AC/BR;AFUC;;;;;;;EAOC,cCcM;ACtBR;AFUC;EACC,cCfW;ACOb;AFYE;EACC,iBAAA;AEVH;AFcG;EACC,aCCI;ACbR;AFiBC;;EAEC,qBC/BW;ACgBb","file":"dark.css","sourcesContent":["// compiled standalone as well as appended to style.scss, so it needs the palette\n@import \"variables\";\n\n.dark {\n\tbackground-color: $forest-800;\n\n\t.page-home .overlay {\n\t\tbackground-color: rgba($forest-900, 0.97);\n\t}\n\n\t.page-title {\n\t\th2 {\n\t\t\tcolor: $light;\n\t\t}\n\n\t\t.title-bg {\n\t\t\tcolor: rgba($sage, 0.06);\n\t\t}\n\t}\n\n\t.section-title h3::before {\n\t\tbackground-color: $light;\n\t}\n\n\th1,\n\th2,\n\th3,\n\th4,\n\th5,\n\th6,\n\t.about-author .author-desc p {\n\t\tcolor: $light;\n\t}\n\t.switcher-body h4 {\n\t\tcolor: $forest-800;\n\t}\n\n\t.service-hex {\n\t\t.st0 {\n\t\t\tfill: transparent;\n\t\t}\n\n\t\t&:hover {\n\t\t\t.st0 {\n\t\t\t\tfill: $light;\n\t\t\t}\n\t\t}\n\t}\n\n\t.testimonials .text,\n\t.btn-border {\n\t\tborder-color: $forest-700;\n\t}\n}","//\n// Typography\n//\n\n$font-stack: \"Libre Baskerville\", serif;\n$open-sans: \"Open Sans\", sans-serif;\n\n//\n// Palette — forest and wood\n//\n// Deep greens for structure, warm browns for everything that needs to stand\n// out, parchment instead of white. No third hue: the accent comes from the\n// brown family, which is why it needs two weights. A single mid-brown either\n// disappears into cream or goes muddy on dark green, so light surfaces get\n// leather and dark surfaces get tan.\n//\n\n// Forest — panels, cards, hexagons, anything structural\n$forest-900: #0d1711; // deepest wells and overlays\n$forest-800: #132018; // dark page backgrounds\n$forest-700: #1b2e21; // cards, hexagons, inputs\n$forest-600: #24402c; // raised surfaces, chips, bars\n$forest-500: #325a3c; // hairlines and borders on dark\n$sage: #8fae7a; // muted green, secondary text on dark\n\n// Wood — the accent family and the warmth under everything\n$bark-900: #2b1e14;\n$bark-700: #443023;\n$bark-500: #6b4c33;\n$bark-300: #9a7551;\n$leather: #8a5230; // accent on parchment: titles, buttons, links\n$leather-deep: #6d3f24; // pressed and hover states\n$tan: #c8a179; // accent on dark: the same job, one surface up\n$tan-dim: #ab8a68; // muted body copy on dark\n\n// Parchment — light surfaces, in place of white\n$parchment: #f4eee1;\n$parchment-dim: #e8dfcb;\n$parchment-line: #d9cbb0;\n\n//\n// Semantic aliases — everything downstream refers to these\n//\n$primary-color: $leather;\n$light-dark: $forest-700;\n$light: #f7f2e7; // warm white for text and rules on dark\n$text-color: #5a4733; // body copy on parchment\n$title-color: #1b2e21; // headings on parchment\n$border-color: $parchment-line;\n\n//\n// Hexagon\n//\n$sqrt3: 1.7320508075688772;\n$edgeSize: 100px;\n$hexWidth: $edgeSize * 2;\n$hexHeight: $sqrt3 * $edgeSize;\n\n// Display\n$borderHover: 15px;\n\n// Easing\n$ease-out-expo: cubic-bezier(0.19, 1, 0.22, 1);\n$ease-out-quart: cubic-bezier(0.165, 0.84, 0.44, 1);\n",".dark {\n  background-color: #132018;\n}\n.dark .page-home .overlay {\n  background-color: rgba(13, 23, 17, 0.97);\n}\n.dark .page-title h2 {\n  color: #f7f2e7;\n}\n.dark .page-title .title-bg {\n  color: rgba(143, 174, 122, 0.06);\n}\n.dark .section-title h3::before {\n  background-color: #f7f2e7;\n}\n.dark h1,\n.dark h2,\n.dark h3,\n.dark h4,\n.dark h5,\n.dark h6,\n.dark .about-author .author-desc p {\n  color: #f7f2e7;\n}\n.dark .switcher-body h4 {\n  color: #132018;\n}\n.dark .service-hex .st0 {\n  fill: transparent;\n}\n.dark .service-hex:hover .st0 {\n  fill: #f7f2e7;\n}\n.dark .testimonials .text,\n.dark .btn-border {\n  border-color: #1b2e21;\n}"]}